    physicalExam: { 'Physical Strength': 'Normal', Mobility: 'Normal', Endurance: 'Normal', 'Tactical Acumen': 'Standard', 'Combat Skill': 'Standard', 'Originium Arts': 'Excellent' },
    talents: [{ name: 'Casting Speed Up', desc: 'ASPD +9', elite: 'E1' }],
