    cv: { JP: 'Kana Hanazawa', CN: 'Shanxin', EN: '', KR: '' },
    trait: 'Can launch Ranged Attacks that deal 80% of normal ATK',
    tags: ['DPS'],
    stats: { hp: 2040, atk: 698, def: 325, res: 10, block: 2, cost: 17, aspd: '1.3s', rdp: '70s' },
